    {"n": "Nói lại với bé", "d": "Chạm và nói: giọng bạn phát ra ở thiết bị của bé, nên bạn dỗ bé mà không cần bước vào phòng."},
    {"n": "Hát ru & nhạc", "d": "Phát âm thanh êm dịu hoặc file MP3 của riêng bạn trên thiết bị của bé, ngay từ điện thoại."},
    {"n": "Đèn ngủ", "d": "Bật ánh sáng ấm dịu trên màn hình thiết bị của bé, từ phía bạn."},
    {"n": "Báo bé khóc", "d": "Nhận cảnh báo khi bé khóc, với độ nhạy do bạn tự đặt, kèm nhật ký sự kiện."},
    {"n": "Hẹn giờ ngủ", "d": "Để bài hát ru phát rồi tự dừng sau khoảng thời gian bạn chọn."},
